func ctNl(b []byte, i int32) int32 {
	var k int32 = i
	for (k < port.BlobLen(b)) && (port.BlobU8(b, k) != 10) {
		k += 1
	}
	return k
}

func ctTab(b []byte, i int32, lim int32) int32 {
	// Index of the next tab in [i, lim), or lim.
	var k int32 = i
	for (k < lim) && (port.BlobU8(b, k) != 9) {
		k += 1
	}
	return k
}

func ctHexval(c int32) int32 {
	if (c >= 48) && (c <= 57) {
		return c - 48
	}
	if (c >= 97) && (c <= 102) {
		return c - 87
	}
	if (c >= 65) && (c <= 70) {
		return c - 55
	}
	return -1
}

func ctHex(b []byte, from int32, to int32) int32 {
	// A hex number; a lone `-` is -1 (none).
	var k int32 = from
	var v int32 = 0
	if ((to - from) == 1) && (port.BlobU8(b, from) == 45) {
		return -1
	}
	for k < to {
		v = (v * 16) + ctHexval(port.BlobU8(b, k))
		k += 1
	}
	return v
}

func ctDec(b []byte, from int32, to int32) int32 {
	// A decimal, possibly negative.
	var k int32 = from
	var v int32 = 0
	var neg int32 = 0
	if (k < to) && (port.BlobU8(b, k) == 45) {
		neg = 1
		k += 1
	}
	for k < to {
		v = (v * 10) + (port.BlobU8(b, k) - 48)
		k += 1
	}
	if neg == 1 {
		return 0 - v
	}
	return v
}

func ctNear(emonT *testing.T, got int32, want int32, tol int32, law string, row int32) int32 {
	var d int32 = got - want
	if d < 0 {
		d = 0 - d
	}
	port.AssertThatAt(emonT, d <= tol, law, row)
	return 0
}

func ctNearAngle(emonT *testing.T, got int32, want int32, law string, row int32) int32 {
	// Centi-degrees, around the circle, within 3: `ev-angle`'s table is good to 0.03 degree.
	var d int32 = got - want
	if d < 0 {
		d = 0 - d
	}
	if d > 18000 {
		d = 36000 - d
	}
	port.AssertThatAt(emonT, d <= 3, law, row)
	return 0
}

