func ctCountPage(gl *port.Cells, page int32) int32 {
	var n int32 = evidence.GlCount(gl)
	var g int32 = 0
	var c int32 = 0
	for g < n {
		if evidence.GlGet(gl, g, evidence.ChPage()) == page {
			c += 1
		}
		g += 1
	}
	return c
}

func ctRealRows(emonT *testing.T, rows []byte) int32 {
	// real.txt: `path page digest glyphs`. The file is one of corpus/ (not committed):
	// the digest of the page's glyph stream and its glyph count are what emon made of it
	// when pdfminer.six agreed, and must not change.
	var ar *port.Cells = port.NewCells()
	var dc *port.Cells = port.NewCells()
	var a *port.Cells = port.NewCells()
	var b *port.Cells = port.NewCells()
	var st *port.Cells = port.NewCells()
	var cx *port.Cells = port.NewCells()
	var ox *port.Cells = port.NewCells()
	var cs *port.Cells = port.NewCells()
	var out *port.Cells = port.NewCells()
	var f0 *port.Cells = port.NewCells()
	var f1 *port.Cells = port.NewCells()
	var f2 *port.Cells = port.NewCells()
	var f3 *port.Cells = port.NewCells()
	var gl *port.Cells = port.NewCells()
	var et *port.Cells = port.NewCells()
	var mk *port.Cells = port.NewCells()
	var fnt *port.Cells = port.NewCells()
	var pg *port.Cells = port.NewCells()
	var wd *port.Cells = port.NewCells()
	var ln *port.Cells = port.NewCells()
	var n int32 = port.BlobLen(rows)
	var pos int32 = 0
	var line int32 = 0
	var e int32 = 0
	var t1 int32 = 0
	var t2 int32 = 0
	var t3 int32 = 0
	var page int32 = 0
	var rowsn int32 = 0
	for pos < n {
		line += 1
		e = ctNl(rows, pos)
		if (pos < e) && (port.BlobU8(rows, pos) != 35) {
			t1 = ctTab(rows, pos, e)
			t2 = ctTab(rows, t1+1, e)
			t3 = ctTab(rows, t2+1, e)
			page = ctDec(rows, t1+1, t2)
			rowsn += 1
			port.AssertEqAt(emonT, ctRun(port.SrcOfBlob(port.TestFileSpan(rows, pos, t1)), ar, dc, a, b, st, cx, ox, cs, out, f0, f1, f2, f3, gl, et, mk, fnt, pg, wd, ln), 0, "the file ran", line)
			port.AssertEqAt(emonT, contentrows.CrDigest(gl, et, page), ctDec(rows, t2+1, t3), "digest of the page's text", line)
			port.AssertEqAt(emonT, ctCountPage(gl, page), ctDec(rows, t3+1, e), "glyphs on the page", line)
		}
		pos = e + 1
	}
	return rowsn
}

