func ctCopy(b []byte, c *port.Cells) int32 {
	var n int32 = port.BlobLen(b)
	var i int32 = 0
	port.CellsDrop(c, 0)
	for i < n {
		port.CellsPush(c, port.BlobU8(b, i))
		i += 1
	}
	return n
}

func ctFuzzFile(emonT *testing.T, bytes []byte, iters int32, cutStep int32) int32 {
	// Flip 1-6 random bytes `iters` times, and cut the file at every `cut-step` bytes; run each.
	// Nothing is asserted but that no run faults, on any target, whatever it says.
	var ar *port.Cells = port.NewCells()
	var dc *port.Cells = port.NewCells()
	var a *port.Cells = port.NewCells()
	var b *port.Cells = port.NewCells()
	var st *port.Cells = port.NewCells()
	var cx *port.Cells = port.NewCells()
	var ox *port.Cells = port.NewCells()
	var cs *port.Cells = port.NewCells()
	var out *port.Cells = port.NewCells()
	var f0 *port.Cells = port.NewCells()
	var f1 *port.Cells = port.NewCells()
	var f2 *port.Cells = port.NewCells()
	var f3 *port.Cells = port.NewCells()
	var gl *port.Cells = port.NewCells()
	var et *port.Cells = port.NewCells()
	var mk *port.Cells = port.NewCells()
	var fnt *port.Cells = port.NewCells()
	var pg *port.Cells = port.NewCells()
	var wd *port.Cells = port.NewCells()
	var ln *port.Cells = port.NewCells()
	var work *port.Cells = port.NewCells()
	var rng *port.Cells = port.NewCells()
	var n int32 = port.BlobLen(bytes)
	var it int32 = 0
	var k int32 = 0
	var flips int32 = 0
	var cut int32 = 0
	var runs int32 = 0
	var at int32 = 0
	splitmix.SmSeed(rng, 4242)
	for it < iters {
		ctCopy(bytes, work)
		flips = 1 + splitmix.SmBelow(rng, 6)
		k = 0
		for k < flips {
			at = splitmix.SmBelow(rng, n)
			port.CellsSet(work, at, splitmix.SmBelow(rng, 256))
			k += 1
		}
		ctRun(port.SrcOfCells(work), ar, dc, a, b, st, cx, ox, cs, out, f0, f1, f2, f3, gl, et, mk, fnt, pg, wd, ln)
		runs += 1
		it += 1
	}
	cut = cutStep
	for cut < n {
		ctCopy(bytes, work)
		port.CellsDrop(work, cut)
		ctRun(port.SrcOfCells(work), ar, dc, a, b, st, cx, ox, cs, out, f0, f1, f2, f3, gl, et, mk, fnt, pg, wd, ln)
		runs += 1
		cut += cutStep
	}
	return runs
}

