func ctGw(gl *port.Cells, x int32, y int32, cp int32) int32 {
	// One glyph of the scene: 500 wide and 800 tall, size 1000, its baseline at y + 800 (centipoints, page 1).
	var g int32 = evidence.GlNew(gl, 1, x, y, x+500, y+800, cp, -1, 0, -1)
	evidence.GlSet(gl, g, evidence.GfSize(), 1000)
	return g
}

func ctRun2g(gl *port.Cells, x int32, y int32, c1 int32, c2 int32) int32 {
	// A word of two glyphs, shown together, starting at x.
	ctGw(gl, x, y, c1)
	ctGw(gl, x+500, y, c2)
	return 0
}

func ctGroup(gl *port.Cells, et *port.Cells, wd *port.Cells, ln *port.Cells) int32 {
	var fnt *port.Cells = port.NewCells()
	return pdfcontent.PcGroup(gl, et, wd, ln, fnt, 1, 0, 0)
}

func TestRunsOfOneBaselineDrawnOutOfOrderAreOneLineInOrderAlongIt(emonT *testing.T) {
	// 'ab' at 1000, then 'ef' at 4500 (a gap wider than two sizes: a line of its own), then the 'cd' between them at 2500, which the
	// producer drew LAST (a bold run, say). In the stream that is three lines; along the baseline it is one, 'ab cd ef'.
	var gl *port.Cells = port.NewCells()
	var et *port.Cells = port.NewCells()
	var wd *port.Cells = port.NewCells()
	var ln *port.Cells = port.NewCells()
	ctRun2g(gl, 1000, 0, 97, 98)
	ctRun2g(gl, 4500, 0, 101, 102)
	ctRun2g(gl, 2500, 0, 99, 100)
	ctGroup(gl, et, wd, ln)
	port.AssertEq(emonT, evidence.WdCount(wd), 3, "three words")
	port.AssertEq(emonT, evidence.LnCount(ln), 1, "one line: the runs share a baseline and, in order of x, each continues the one before it")
	port.AssertEq(emonT, evidence.LnGet(ln, 0, evidence.LhFirst()), 0, "it starts at the first word")
	port.AssertEq(emonT, evidence.LnGet(ln, 0, evidence.LhCount()), 3, "and holds the three")
	port.AssertEq(emonT, evidence.WdGet(wd, 0, evidence.HdX0()), 1000, "the first word is the leftmost")
	port.AssertEq(emonT, evidence.WdGet(wd, 1, evidence.HdX0()), 2500, "the second is the one drawn last")
	port.AssertEq(emonT, evidence.WdGet(wd, 2, evidence.HdX0()), 4500, "the third is the rightmost")
	port.AssertEq(emonT, evidence.GlGet(gl, 4, evidence.ChWord()), 1, "the glyphs of the word that moved point at it")
	port.AssertEq(emonT, evidence.GlGet(gl, 2, evidence.ChWord()), 2, "and those of the word it passed")
	port.AssertEq(emonT, evidence.WdGet(wd, 0, evidence.HdLine()), 0, "every word is in the line")
	port.AssertEq(emonT, evidence.WdGet(wd, 2, evidence.HdLine()), 0, "the last too")
	port.AssertEq(emonT, evidence.WdGet(wd, 1, evidence.WfWbreak()), evidence.WbGap(), "a word that ended a run of its own has not ended the line")
	port.AssertEq(emonT, evidence.WdGet(wd, 2, evidence.WfWbreak()), evidence.WbLineEnd(), "the last word ends it")
}

func TestRunsInOrderOrTooFarApartOrOverprintedStayTheLinesTheyWere(emonT *testing.T) {
	var gl *port.Cells = port.NewCells()
	var et *port.Cells = port.NewCells()
	var wd *port.Cells = port.NewCells()
	var ln *port.Cells = port.NewCells()
	// In order along the baseline, with a wide gap between: two lines, as ever (a gutter, a table cell).
	ctRun2g(gl, 1000, 0, 97, 98)
	ctRun2g(gl, 4500, 0, 101, 102)
	ctGroup(gl, et, wd, ln)
	port.AssertEq(emonT, evidence.LnCount(ln), 2, "in order and apart: two lines")
	port.AssertEq(emonT, evidence.WdGet(wd, 1, evidence.HdX0()), 4500, "nothing moved")
	// Out of order, but the word drawn last does not bridge the gap: still apart, nothing moves.
	port.CellsDrop(gl, 0)
	port.CellsDrop(et, 0)
	port.CellsDrop(wd, 0)
	port.CellsDrop(ln, 0)
	ctRun2g(gl, 1000, 0, 97, 98)
	ctRun2g(gl, 9000, 0, 101, 102)
	ctRun2g(gl, 2500, 0, 99, 100)
	ctGroup(gl, et, wd, ln)
	port.AssertEq(emonT, evidence.LnCount(ln), 3, "a chain that does not close: three lines")
	port.AssertEq(emonT, evidence.WdGet(wd, 1, evidence.HdX0()), 9000, "and the stream order is kept")
	// The same word drawn twice, a little to the right (a faked bold): the copies overlap, so they are not one line.
	port.CellsDrop(gl, 0)
	port.CellsDrop(et, 0)
	port.CellsDrop(wd, 0)
	port.CellsDrop(ln, 0)
	ctRun2g(gl, 1000, 0, 97, 98)
	ctRun2g(gl, 1100, 0, 97, 98)
	ctGroup(gl, et, wd, ln)
	port.AssertEq(emonT, evidence.LnCount(ln), 2, "an overprint is two lines, as before")
	// Runs of different baselines are never merged.
	port.CellsDrop(gl, 0)
	port.CellsDrop(et, 0)
	port.CellsDrop(wd, 0)
	port.CellsDrop(ln, 0)
	ctRun2g(gl, 1000, 0, 97, 98)
	ctRun2g(gl, 4500, 0, 101, 102)
	ctRun2g(gl, 2500, 1000, 99, 100)
	ctGroup(gl, et, wd, ln)
	port.AssertEq(emonT, evidence.LnCount(ln), 3, "the word on the next line stays on it")
}

func ctGx(gl *port.Cells, x0 int32, x1 int32, cp int32, bx0 int32, bx1 int32) int32 {
	// One glyph of the scene: the box [x0, x1] by 800, the baseline segment [bx0, bx1] (0, 0 for none), size 1000.
	var g int32 = evidence.GlNew(gl, 1, x0, 0, x1, 800, cp, -1, 0, -1)
	evidence.GlSet(gl, g, evidence.GfSize(), 1000)
	evidence.GlSet(gl, g, evidence.GfBx0(), bx0)
	evidence.GlSet(gl, g, evidence.GfBx1(), bx1)
	return g
}

func TestLeaningGlyphsOfASyntheticItalicMakeOneWord(emonT *testing.T) {
	// Smoke B I-6: a Tm of `12 0 4.1041 12 x y` leans the cell, so the box of each glyph overhangs its baseline segment on both
	// sides by the shear times the cell's height. Three glyphs of 500 whose boxes overhang by 300 on each side: the box of one
	// ends 600 past where the next one's begins, further back than a word allows, but the baselines meet.
	var gl *port.Cells = port.NewCells()
	var et *port.Cells = port.NewCells()
	var wd *port.Cells = port.NewCells()
	var ln *port.Cells = port.NewCells()
	ctGx(gl, 700, 1800, 1055, 1000, 1500)
	ctGx(gl, 1200, 2300, 1088, 1500, 2000)
	ctGx(gl, 1700, 2800, 1080, 2000, 2500)
	ctGroup(gl, et, wd, ln)
	port.AssertEq(emonT, evidence.WdCount(wd), 1, "one word, not three letters")
	port.AssertEq(emonT, evidence.WdGet(wd, 0, evidence.HdTlen()), 3, "of three code points")
}

func ctGs(gl *port.Cells, x0 int32, x1 int32, cp int32, size int32, by int32) int32 {
	// One glyph of the scene: the box [x0, x1] by 800, set in `size`, its baseline segment at height `by`.
	var g int32 = evidence.GlNew(gl, 1, x0, 0, x1, 800, cp, -1, 0, -1)
	evidence.GlSet(gl, g, evidence.GfSize(), size)
	evidence.GlSet(gl, g, evidence.GfBx0(), x0)
	evidence.GlSet(gl, g, evidence.GfBx1(), x1)
	evidence.GlSet(gl, g, evidence.GfBy0(), by)
	evidence.GlSet(gl, g, evidence.GfBy1(), by)
	return g
}

func TestAWordsBaselineIsNotItsRaisedMarker(emonT *testing.T) {
	// P12.7 (smoke A N2): `bread` and a raised, smaller `1,` (a footnote marker: set at 600 where the letters are 1000, its baseline 300 above theirs) are one word `bread1,`. Its baseline ends where its letters'
	// do, not at the marker: the rows of a table sort their words by that baseline, and `bread1,` came before `White` on the row it ends. A marker that begins a word is no more the start of its baseline.
	var gl *port.Cells = port.NewCells()
	var et *port.Cells = port.NewCells()
	var wd *port.Cells = port.NewCells()
	var ln *port.Cells = port.NewCells()
	ctGs(gl, 1000, 1500, 98, 1000, 800)
	ctGs(gl, 1500, 2000, 114, 1000, 800)
	ctGs(gl, 2000, 2300, 49, 600, 500)
	ctGs(gl, 2300, 2600, 44, 600, 500)
	ctGroup(gl, et, wd, ln)
	port.AssertEq(emonT, evidence.WdCount(wd), 1, "one word")
	port.AssertEq(emonT, evidence.WdGet(wd, 0, evidence.HdBy0()), 800, "its baseline begins at its first letter's")
	port.AssertEq(emonT, evidence.WdGet(wd, 0, evidence.HdBy1()), 800, "and ends at its last letter's, not at the raised marker's")
	port.CellsDrop(gl, 0)
	port.CellsDrop(et, 0)
	port.CellsDrop(wd, 0)
	port.CellsDrop(ln, 0)
	ctGs(gl, 1000, 1300, 51, 600, 500)
	ctGs(gl, 1300, 1800, 98, 1000, 800)
	ctGs(gl, 1800, 2300, 114, 1000, 800)
	ctGroup(gl, et, wd, ln)
	port.AssertEq(emonT, evidence.WdCount(wd), 1, "a marker that begins the word: one word")
	port.AssertEq(emonT, evidence.WdGet(wd, 0, evidence.HdBy0()), 800, "its baseline begins at the letters'")
	port.AssertEq(emonT, evidence.WdGet(wd, 0, evidence.HdBy1()), 800, "and ends there")
}

func TestWordBaselineSizeComparisonsDoNotOverflow(emonT *testing.T) {
	var gl *port.Cells = port.NewCells()
	// The identity fuzz corpus contains huge glyph sizes. Comparing eighty per cent must work at the I32 limit, including the strict threshold, without multiplication overflow on any target.
	ctGs(gl, 1000, 1500, 98, 1000, 800)
	ctGs(gl, 1500, 1800, 49, 600, 500)
	evidence.GlSet(gl, 0, evidence.GfSize(), 2147483647)
	evidence.GlSet(gl, 1, evidence.GfSize(), 1000000000)
	port.AssertEq(emonT, pdfcontent.PcBaseGlyph(gl, 0, 1, 0), 0, "huge letters supply the start")
	port.AssertEq(emonT, pdfcontent.PcBaseGlyph(gl, 0, 1, 1), 0, "the smaller marker cannot supply the end")
	evidence.GlSet(gl, 1, evidence.GfSize(), 1717986917)
	port.AssertEq(emonT, pdfcontent.PcBaseGlyph(gl, 0, 1, 1), 0, "the integer just below eighty per cent stays small")
	evidence.GlSet(gl, 1, evidence.GfSize(), 1717986918)
	port.AssertEq(emonT, pdfcontent.PcBaseGlyph(gl, 0, 1, 1), 1, "the next integer is above the threshold")
}

func TestADiacriticDrawnOverALetterIsTheCombiningMarkAfterIt(emonT *testing.T) {
	// Smoke B I-21: TeX draws an umlaut as the dieresis glyph and then the u, backed up under it: `M` `dieresis` `u` `ller`. The
	// word is Mu, U+0308, ller; the paragraph's normalisation composes it. A dieresis that is not over the letter after it is left.
	var gl *port.Cells = port.NewCells()
	var et *port.Cells = port.NewCells()
	var wd *port.Cells = port.NewCells()
	var ln *port.Cells = port.NewCells()
	ctGx(gl, 1000, 1500, 77, 1000, 1500)
	ctGx(gl, 1650, 1950, 168, 1650, 1950)
	ctGx(gl, 1500, 2000, 117, 1500, 2000)
	ctGx(gl, 2000, 2500, 108, 2000, 2500)
	ctGx(gl, 2500, 3000, 108, 2500, 3000)
	ctGx(gl, 3000, 3500, 101, 3000, 3500)
	ctGx(gl, 3500, 4000, 114, 3500, 4000)
	ctGroup(gl, et, wd, ln)
	port.AssertEq(emonT, evidence.WdCount(wd), 1, "one word")
	port.AssertEq(emonT, evidence.WdGet(wd, 0, evidence.HdTlen()), 7, "of seven code points: the dieresis is written after the u")
	port.AssertEq(emonT, port.CellsAt(et, evidence.WdGet(wd, 0, evidence.HdTstart())+1), 117, "the letter first")
	port.AssertEq(emonT, port.CellsAt(et, evidence.WdGet(wd, 0, evidence.HdTstart())+2), 776, "then U+0308")
	// a spacing acute standing apart, as an apostrophe (it's), over nothing: not a combining mark
	port.CellsDrop(gl, 0)
	port.CellsDrop(et, 0)
	port.CellsDrop(wd, 0)
	port.CellsDrop(ln, 0)
	ctGx(gl, 1000, 1500, 105, 1000, 1500)
	ctGx(gl, 1500, 1800, 180, 1500, 1800)
	ctGx(gl, 1800, 2300, 115, 1800, 2300)
	ctGroup(gl, et, wd, ln)
	port.AssertEq(emonT, evidence.WdGet(wd, 0, evidence.HdTlen()), 3, "three code points, in the order they were shown")
	port.AssertEq(emonT, port.CellsAt(et, evidence.WdGet(wd, 0, evidence.HdTstart())+1), 180, "the acute is itself")
}

func TestAdobesSymbolPrivateUseIsTheDelimiterPiecesUnicodeNames(emonT *testing.T) {
	port.AssertEq(emonT, pdfcontent.PcPua(63726), 9121, "U+F8EE, bracketlefttp, is U+23A1")
	port.AssertEq(emonT, pdfcontent.PcPua(63728), 9123, "U+F8F0, bracketleftbt, is U+23A3")
	port.AssertEq(emonT, pdfcontent.PcPua(63739), 9126, "U+F8FB, bracketrightbt, is U+23A6")
	port.AssertEq(emonT, pdfcontent.PcPua(63723), 9115, "U+F8EB, parenlefttp, is U+239B")
	port.AssertEq(emonT, pdfcontent.PcPua(63742), 9133, "U+F8FE, bracerightbt, is U+23AD")
	port.AssertEq(emonT, pdfcontent.PcPua(63733), 9134, "U+F8F5, integralex, is U+23AE")
	port.AssertEq(emonT, pdfcontent.PcPua(65), 65, "a letter is itself")
	port.AssertEq(emonT, pdfcontent.PcPua(-1), -1, "no value stays none")
	port.AssertEq(emonT, pdfcontent.PcPua(57344), 57344, "a private-use code point of anyone else's is not touched")
}

func TestACombiningMarkDoesNotOpenAWordGap(emonT *testing.T) {
	var gl *port.Cells = port.NewCells()
	var et *port.Cells = port.NewCells()
	var wd *port.Cells = port.NewCells()
	var ln *port.Cells = port.NewCells()
	ctGw(gl, 1000, 0, 1488)
	var mark int32 = ctGw(gl, 1200, 600, 1456)
	evidence.GlSet(gl, mark, evidence.GfBy0(), 1400)
	evidence.GlSet(gl, mark, evidence.GfBy1(), 1400)
	ctGw(gl, 1500, 0, 1489)
	ctGroup(gl, et, wd, ln)
	port.AssertEq(emonT, evidence.WdCount(wd), 1, "niqqud belongs to its base despite its displaced baseline")
}
